<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {AlertCircle,ArrowRight,Check,CheckCircle2,Copy,LoaderCircle,Pencil,RefreshCw,ShieldCheck,Trash2,Upload,X} from 'lucide-vue-next';
import ApprovalReview from './ApprovalReview.vue';
import BiAppSettingsForm from './BiAppSettingsForm.vue';
import PublicationRecovery from './PublicationRecovery.vue';
import DeletionRecovery from './DeletionRecovery.vue';
import {createRequestGuard} from '../lib/async-response';
type Item=Record<string,any>;
type ManualAction='update_app_details'|'clone_app'|'clone_flow'|'delete_draft'|'publish_app'|'publish_flow';
const props=defineProps<{tenant:string;tenantName:string;resource:Item;desks:Item[];management?:Item|null;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{updated:[];configured:[resource:string];deleted:[];published:[resource:string];project:[id:string];notice:[message:string];active:[value:boolean]}>();
const mode=ref<ManualAction|null>(null);
watch(mode,value=>emit('active',value!==null),{immediate:true});
const isFlow=computed(()=>props.resource.kind==='flow');const cloneAction=computed<ManualAction>(()=>isFlow.value?'clone_flow':'clone_app');const cloning=computed(()=>mode.value==='clone_app'||mode.value==='clone_flow');
const publishAction=computed<ManualAction>(()=>isFlow.value?'publish_flow':'publish_app');const publishing=computed(()=>mode.value==='publish_app'||mode.value==='publish_flow');
const publishMode=ref<'new'|'replace'>('new');const publishDesk=ref('');const copyData=ref(false);
watch(publishMode,value=>{publishDesk.value=value==='replace'?String(props.management?.publication_origin?.desk_id??''):'';if(value==='new')copyData.value=false;});
const name=ref('');const requestId=ref('');const review=ref<Item|null>(null);const project=ref<Item|null>(null);
const busy=ref(false);const error=ref('');const clock=ref(Date.now());const nameInput=ref<HTMLInputElement|null>(null);const publishModeInput=ref<HTMLSelectElement|null>(null);const publishDeskInput=ref<HTMLSelectElement|null>(null);const reviewHeading=ref<HTMLElement|null>(null);
const selection=createRequestGuard();
let pollBusy=false;let completed=false;let poll:ReturnType<typeof setInterval>|undefined;
const expired=computed(()=>review.value?.status==='pending'&&new Date(review.value.expires_at).getTime()<=clock.value);
const deciding=computed(()=>review.value?.status==='pending'&&!expired.value);
const executing=computed(()=>['approved','executing'].includes(review.value?.status));
const result=computed<Item>(()=>review.value?.payload?.execution?.result??{});
const copied=computed(()=>review.value?.status==='completed'&&cloning.value&&new RegExp('^'+(isFlow.value?'flow':'app')+':[1-9][0-9]*$').test(result.value.managed_resource??''));
const deletionVerified=computed(()=>mode.value==='delete_draft'&&review.value?.status==='completed'&&result.value.deletion?.verified===true&&result.value.deletion?.resource===`${props.resource.kind}:${props.resource.id}`);
const published=computed(()=>review.value?.status==='completed'&&publishing.value&&result.value.publication?.verified===true);
const ended=computed(()=>!!review.value&&!deciding.value&&!executing.value);
async function start(action:ManualAction){
 if((isFlow.value&&!['clone_flow','publish_flow','delete_draft'].includes(action))||(!isFlow.value&&['clone_flow','publish_flow'].includes(action))||(action==='delete_draft'&&!props.management?.can_delete_draft)||props.management?.deletion_pending||busy.value||executing.value||(['publish_app','publish_flow'].includes(action)&&!props.management?.can_publish))return;
 selection.next();mode.value=action;review.value=null;project.value=null;error.value='';completed=false;requestId.value=crypto.randomUUID();name.value=Array.from('Cópia de '+props.resource.name).slice(0,100).join('');publishMode.value='new';publishDesk.value='';copyData.value=false;
 await nextTick();if(cloning.value)nameInput.value?.focus();else if(publishing.value)(publishModeInput.value??publishDeskInput.value)?.focus();
}
async function prepare(){
 if(!mode.value||busy.value||props.management?.deletion_pending||(publishing.value&&!/^[1-9][0-9]*$/.test(publishDesk.value)))return;
 const current=selection.current();busy.value=true;error.value='';
 try{const response=await props.request(`/catalog/${props.tenant}/${isFlow.value?'flows':'apps'}/${props.resource.id}/actions`,'POST',{action:mode.value,request_id:requestId.value,...(cloning.value?{name:name.value.trim()}:publishing.value?{desk:Number(publishDesk.value),publish_mode:publishMode.value,...(isFlow.value?{copy_data:copyData.value}:{})}:{})});if(!current())return;if(typeof response.approval?.status!=='string')throw new Error('Não foi possível confirmar o estado da revisão. Tente novamente para recuperar esta solicitação.');review.value=response.approval;project.value=response.project;emit('updated');await nextTick();if(current())reviewHeading.value?.focus();}
 catch(e){if(current())error.value=(e as Error).message;}finally{if(current())busy.value=false;}
}
async function refreshStatus(){
 if(!executing.value||pollBusy||!review.value)return;
 const id=review.value.id;const current=selection.current();pollBusy=true;
 try{const response=await props.request(`/bi-actions/${id}`);if(!current()||review.value?.id!==id)return;review.value=response.approval;project.value=response.project;error.value='';
  if(review.value?.status==='completed'&&!completed){completed=true;emit('updated');if(deletionVerified.value){emit('notice',isFlow.value?'ETL de teste e tabelas excluídos e conferidos.':'Aplicação de teste excluída e tabelas vinculadas preservadas, com conferência.');emit('deleted');}else if(mode.value==='delete_draft')emit('notice','A operação foi registrada em uma versão anterior, sem comprovante de conferência. Consulte o catálogo antes de outra ação.');else if(publishing.value&&result.value.publication?.verified){emit('notice',(isFlow.value?'ETL publicado na mesa ':'Aplicação publicada na mesa ')+result.value.publication.destination.name+'.');emit('published',result.value.publication.resource);}else emit('notice',result.value.management_warning??'Cópia criada na sua mesa. Você já pode abrir o projeto dela.');}
  else if(review.value?.status==='failed')emit('updated');
 }catch(e){if(current())error.value=(e as Error).message;}finally{pollBusy=false;}
}
async function decide(decision:'approved'|'rejected'){
 if(!deciding.value||!review.value||busy.value||(decision==='approved'&&props.management?.deletion_pending))return;
 const current=selection.current();const id=review.value.id;busy.value=true;error.value='';
 try{const response=await props.request(`/approvals/${id}/decide`,'POST',{decision,fingerprint:review.value.fingerprint});if(!current())return;review.value=response;emit('updated');if(decision==='approved')await refreshStatus();}
 catch(e){if(current())error.value=(e as Error).message;}finally{if(current())busy.value=false;}
}
function recovered(response:Item){review.value=response.approval;project.value=response.project;completed=true;emit('updated');emit('notice','Publicação confirmada na mesa '+result.value.publication.destination.name+'.');emit('published',result.value.publication.resource);}
function recoveredDeletion(response:Item){review.value=response.approval;project.value=response.project;completed=true;emit('updated');emit('notice',isFlow.value?'Exclusão do ETL e das tabelas conferida, sem novo envio.':'Exclusão da aplicação conferida, com fontes preservadas e sem novo envio.');emit('deleted');}
function dismiss(){if(busy.value||executing.value||deciding.value)return;selection.invalidate();mode.value=null;review.value=null;project.value=null;error.value='';}
onMounted(()=>{poll=setInterval(()=>{clock.value=Date.now();if(!document.hidden)refreshStatus();},2200);});
onUnmounted(()=>{emit('active',false);selection.invalidate();if(poll)clearInterval(poll);});
</script>

<template>
 <section class="manual-bi-action" :aria-label="isFlow?'Gerenciar ETL':'Gerenciar aplicação'">
  <div class="manual-heading"><ShieldCheck :size="18"/><div><strong>{{isFlow?'Gerenciar ETL':'Gerenciar aplicação'}}</strong><p>{{management?.deletion_pending?'Uma exclusão está em conferência. Use Conferir exclusão na conversa ou em Atividade antes de editar, duplicar ou publicar este recurso.':'Use sua conexão BI. Estas ações não iniciam uma tarefa de IA.'}}</p></div></div>
  <div v-if="!mode" class="manual-buttons"><button v-if="!isFlow" class="secondary-button" data-tour="catalog-app-details" :disabled="management?.deletion_pending" @click="start('update_app_details')"><Pencil :size="16"/>Editar nome e descrição</button><button class="secondary-button" :disabled="management?.deletion_pending" @click="start(cloneAction)"><Copy :size="16"/>{{isFlow?'Duplicar ETL':'Duplicar aplicação'}}</button><button v-if="management?.can_publish" class="secondary-button" @click="start(publishAction)"><Upload :size="16"/>{{isFlow?'Publicar ETL':'Publicar aplicação'}}</button><button v-if="management?.can_delete_draft" class="danger-text" @click="start('delete_draft')"><Trash2 :size="15"/>Excluir rascunho criado aqui</button></div>
  <BiAppSettingsForm v-else-if="mode==='update_app_details'" :tenant="tenant" :tenant-name="tenantName" :resource="resource" :request="request" @close="mode=null" @updated="emit('updated')" @notice="emit('notice',$event)" @saved="mode=null;emit('configured',$event)"/>
  <template v-else-if="!review">
   <form @submit.prevent="prepare"><template v-if="cloning"><h3>Uma cópia para trabalhar</h3><p>{{isFlow?'Duplique a definição deste ETL para trabalhar em um projeto próprio. A cópia fica em Minha Mesa e precisa de conferência e teste de carga antes de usar seus dados.':'A aplicação original permanece como está. A cópia terá um novo projeto e ficará na sua mesa.'}}</p><label>Nome da cópia<input ref="nameInput" v-model="name" :disabled="busy" required maxlength="100" :placeholder="isFlow?'Ex.: Minha carga financeira':'Ex.: Minha visão comercial'" :aria-label="isFlow?'Nome da cópia do ETL':'Nome da cópia da aplicação'"></label></template><template v-else-if="publishing"><h3>{{isFlow?'Publicar ETL':'Publicar aplicação'}}</h3><p>{{isFlow?'Compartilhe a preparação dos dados e suas tabelas com os usuários de uma mesa de dados.':'Compartilhe esta versão com os usuários de uma mesa de aplicações.'}}</p><label v-if="management?.publication_origin">Como publicar<select ref="publishModeInput" v-model="publishMode" :disabled="busy" aria-label="Modo de publicação"><option value="new">{{isFlow?'Como um novo ETL':'Como uma nova aplicação'}}</option><option value="replace">Substituir a versão original</option></select></label><p v-else class="manual-status">Esta publicação criará uma nova entrada na mesa escolhida.</p><label v-if="publishMode==='new'">{{isFlow?'Mesa de dados':'Mesa de aplicações'}}<select ref="publishDeskInput" v-model="publishDesk" required :disabled="busy" :aria-label="isFlow?'Mesa de dados para publicação':'Mesa de publicação'"><option value="">Escolha onde compartilhar</option><option v-for="desk in desks" :key="desk.id" :value="String(desk.id)">{{desk.name}}</option></select></label><p v-else class="publication-target">A versão <strong>{{management?.publication_origin?.name}}</strong> será substituída na mesa <strong>{{management?.publication_origin?.desk_name}}</strong>.</p><label v-if="isFlow&&publishMode==='replace'" class="copy-data-choice"><input v-model="copyData" type="checkbox" :disabled="busy"><span>Copiar também os dados da versão de teste para a tabela original<small>Confira primeiro se a tabela de teste contém os dados pretendidos. Essa escolha não executa uma nova consulta à fonte.</small></span></label><p v-if="!desks.length" class="manual-status">Não há mesas disponíveis nesta consulta. Atualize o catálogo e confira as permissões da sua conta.</p><p v-if="isFlow">A publicação não inicia carga nem cria agenda. A revisão apresenta as tabelas e eventuais alterações de campos; depois, confira os dados e a atualização automática.</p><p v-else>As fontes precisam ter agenda ativa ao menos diária e carga concluída. O sistema confere isso antes de preparar a revisão.</p></template><template v-else><h3>Excluir este rascunho?</h3><p>{{isFlow?'A exclusão remove este ETL e suas tabelas de destino, incluindo os dados de teste carregados. A revisão apresentará os destinos. A conexão e a versão original serão preservadas; vínculos com aplicações e agendas precisam ser resolvidos antes de excluir.':'A exclusão remove esta aplicação de teste e seus dashboards. A revisão identifica os painéis e as tabelas vinculadas que serão preservadas. A aplicação original, as fontes de dados e as agendas serão preservadas; o resultado precisa ser conferido no BI.'}}</p></template><div v-if="error" class="form-error" role="alert"><AlertCircle :size="16"/>{{error}}</div><div class="manual-buttons"><button type="button" class="secondary-button" :disabled="busy" @click="dismiss">Voltar</button><button class="primary-button" :disabled="busy||management?.deletion_pending||(cloning&&!name.trim())||(publishing&&!publishDesk)"><LoaderCircle v-if="busy" :size="15" class="spin"/><ShieldCheck v-else :size="15"/>Preparar revisão</button></div></form>
  </template>
  <template v-else>
   <template v-if="deciding"><h3 ref="reviewHeading" tabindex="-1">Confira antes de autorizar</h3><ApprovalReview :approval="review" :tenants="[{id:tenant,name:tenantName}]"/><div class="manual-buttons"><button class="secondary-button" :disabled="busy" @click="decide('rejected')"><X :size="15"/>Recusar</button><button class="primary-button" :disabled="busy||management?.deletion_pending" @click="decide('approved')"><LoaderCircle v-if="busy" :size="15" class="spin"/><Check v-else :size="15"/>{{cloning?'Autorizar duplicação':publishing?(review.payload.action.publish_mode==='replace'?'Autorizar substituição':'Autorizar publicação'):'Autorizar exclusão'}}</button></div></template>
   <div v-else-if="executing" class="manual-progress" role="status"><LoaderCircle :size="20" class="spin"/><div><strong>{{review.status==='approved'?'Aguardando execução':'Executando no BI'}}</strong><p>Você pode acompanhar esta operação também em Atividade.</p></div><button class="icon-button" aria-label="Atualizar operação de BI" @click="refreshStatus"><RefreshCw :size="16"/></button></div>
   <div v-else-if="copied" class="manual-success" role="status"><CheckCircle2 :size="22"/><div><strong>Cópia criada na sua mesa</strong><p>{{result.confirmed_name||'Projeto: '+review.payload.action.name}}</p><p v-if="result.management_warning" class="form-error" role="alert">{{result.management_warning}}</p><p v-if="isFlow">Abra o projeto e peça à IA para conferir as etapas e testar a carga. Uma cópia ainda não significa dados carregados.</p><p v-else>Confira a atualização das fontes antes de publicar a cópia.</p><p v-if="isFlow&&result.flow_clone?.verified">{{result.flow_clone.node_count}} {{result.flow_clone.node_count===1?'etapa conferida':'etapas conferidas'}} · {{result.flow_clone.table_refs.length}} {{result.flow_clone.table_refs.length===1?'nova tabela':'novas tabelas'}} de destino.</p><button v-if="project" class="primary-button" @click="emit('project',project.id)">Abrir projeto da cópia<ArrowRight :size="15"/></button></div></div>
   <div v-else-if="published" class="manual-success" role="status"><CheckCircle2 :size="22"/><div><strong>{{isFlow?'ETL publicado':'Aplicação publicada'}}</strong><p>{{result.publication.name}} · {{result.publication.destination.name}}</p><p v-if="isFlow">{{result.publication.message}}</p><button v-if="project" class="primary-button" @click="emit('project',project.id)">Abrir projeto<ArrowRight :size="15"/></button></div></div>
   <div v-else-if="review.status==='completed'&&result.management_warning" class="form-error" role="alert"><AlertCircle :size="18"/>{{result.management_warning}}</div>
   <div v-else-if="review.status==='failed'" class="manual-failure" role="alert"><AlertCircle :size="20"/><div><strong>Esta operação precisa de atenção</strong><p>{{review.payload.execution?.message}}</p><p>Confira o recurso no catálogo antes de solicitar outra operação.</p><PublicationRecovery :approval="review" :request="request" @confirmed="recovered"/><DeletionRecovery :approval="review" :request="request" @confirmed="recoveredDeletion"/></div></div>
   <p v-else class="manual-status" role="status">{{expired||review.status==='expired'?'Esta revisão expirou. Prepare outra para conferir o estado atual.':review.status==='rejected'?'Operação recusada. Nenhuma ação desta revisão foi executada.':review.status==='cancelled'?'Operação cancelada.':review.status==='completed'?(mode==='delete_draft'?(deletionVerified?'Exclusão conferida.':'Operação registrada na versão anterior, sem comprovante de conferência. Consulte o catálogo antes de outra ação.'):'Operação concluída.'):'Estado indisponível. Consulte Atividade antes de solicitar outra operação.'}}</p>
   <div v-if="error" class="form-error" role="alert"><AlertCircle :size="16"/>{{error}}</div><button v-if="ended" class="secondary-button manual-back" @click="dismiss">Voltar às ações</button>
  </template>
 </section>
</template>

<style scoped>
.manual-bi-action{margin-top:22px;border:1px solid #dce6f5;border-radius:10px;padding:18px;background:#f8fbff}.manual-heading{display:flex;gap:10px;align-items:flex-start;color:#355b91;margin-bottom:14px}.manual-heading strong{font-size:13px}.manual-heading p,.manual-bi-action form>p,.manual-progress p,.manual-success p,.manual-failure p,.manual-status{font-size:12px;color:#68778f;line-height:1.7;margin:5px 0 12px}.manual-bi-action h3{font-size:14px;font-weight:650;color:#253b5a;margin-bottom:9px}.manual-bi-action h3[tabindex="-1"]:focus{outline:2px solid #2563eb;outline-offset:4px;border-radius:3px}.manual-bi-action label{display:block;max-width:520px;margin:16px 0}.manual-bi-action input,.manual-bi-action select{display:block;width:100%;background:white}.manual-buttons{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:13px}.manual-buttons .danger-text{display:flex;align-items:center;gap:7px;padding:10px}.manual-progress,.manual-success,.manual-failure{display:flex;align-items:flex-start;gap:12px;background:white;border:1px solid #dce6f5;padding:15px;border-radius:8px}.manual-progress strong,.manual-success strong,.manual-failure strong{font-size:13px}.manual-progress>button{margin-left:auto}.manual-success{color:#287655}.manual-success p{margin-bottom:12px}.manual-failure{color:#99552c}.manual-back{margin-top:13px}.manual-bi-action :deep(.approval-review){margin:12px 0}.copy-data-choice{display:flex!important;gap:10px;align-items:flex-start}.copy-data-choice input{width:16px;height:16px;margin-top:3px;flex-shrink:0}.copy-data-choice span{font-size:12px;line-height:1.7;color:#334c6f}.copy-data-choice small{display:block;color:#68778f;margin-top:5px}.publication-target{padding:12px;border:1px solid #efdfbe;border-radius:7px;background:#fff8eb}.manual-bi-action .form-error{margin:12px 0}@media(max-width:650px){.manual-bi-action{padding:14px}.manual-buttons>button{flex-grow:1}}
</style>
